"use client";

/**
 * Speech playback manager - one utterance at a time.
 *
 *  - "provider" playback: audio generated by the backend TTS provider (Sarvam).
 *  - "browser"  playback: window.speechSynthesis (used when the backend has no TTS key,
 *    the provider failed, or the backend is unreachable). The UI shows which one is used.
 *
 * Starting a new utterance always cancels the previous one (no overlapping audio).
 */

import { useSyncExternalStore } from "react";
import { synthesizeSpeech } from "./api/voice";

export type SpeechStatus = "idle" | "loading" | "speaking" | "error";
export type SpeechKind = "provider" | "browser" | null;

interface SpeechState {
  status: SpeechStatus;
  kind: SpeechKind;
  message: string | null;
  voiceReplies: boolean;
}

const REPLIES_KEY = "sagarvani.voiceReplies";

function readStoredReplies(): boolean {
  try {
    return window.localStorage.getItem(REPLIES_KEY) !== "off";
  } catch {
    return true;
  }
}

let state: SpeechState = { status: "idle", kind: null, message: null, voiceReplies: true };
let hydrated = false;
const listeners = new Set<() => void>();
let token = 0;
let audioEl: HTMLAudioElement | null = null;
let abort: AbortController | null = null;

function set(patch: Partial<SpeechState>) {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
}

function subscribe(l: () => void) {
  listeners.add(l);
  if (!hydrated && typeof window !== "undefined") {
    hydrated = true;
    state = { ...state, voiceReplies: readStoredReplies() };
  }
  return () => listeners.delete(l);
}

const getSnapshot = () => state;
const getServerSnapshot = () => state;

export function useSpeech() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export function setVoiceReplies(on: boolean) {
  try {
    window.localStorage.setItem(REPLIES_KEY, on ? "on" : "off");
  } catch {
    /* storage unavailable (private mode) - setting just won't persist */
  }
  if (!on) stopSpeech();
  set({ voiceReplies: on });
}

export function stopSpeech() {
  token++;
  abort?.abort();
  abort = null;
  if (audioEl) {
    audioEl.pause();
    audioEl.src = "";
    audioEl = null;
  }
  if (typeof window !== "undefined" && "speechSynthesis" in window) window.speechSynthesis.cancel();
  set({ status: "idle", kind: null, message: null });
}

/** Speak only when the user has voice replies enabled. */
export function speakIfEnabled(text: string, language = "en") {
  if (state.voiceReplies) void speak(text, language);
}

export async function speak(text: string, language = "en"): Promise<void> {
  stopSpeech();
  const my = token;
  if (!text.trim()) return;
  set({ status: "loading", kind: null, message: null });

  let chunks: string[] = localChunks(text);
  let providerAudio: string[] = [];
  let mime = "audio/wav";
  let note: string | null = null;

  try {
    abort = new AbortController();
    const tts = await synthesizeSpeech(text, language, abort.signal);
    if (my !== token) return;
    if (tts.chunks.length) chunks = tts.chunks;
    if (tts.isProviderAudio) {
      providerAudio = tts.audioBase64;
      mime = tts.mimeType || mime;
    }
    note = tts.warning;
  } catch (e) {
    if (my !== token) return; // cancelled
    note = `Voice service unavailable (${e instanceof Error ? e.message : "unknown"}); using browser speech.`;
  }

  try {
    if (providerAudio.length) {
      await playProvider(providerAudio, mime, my);
    } else {
      await playBrowser(chunks, language, my, note);
    }
    if (my === token) set({ status: "idle", kind: null, message: null });
  } catch (e) {
    if (my !== token) return;
    set({ status: "error", kind: null, message: e instanceof Error ? e.message : "Playback failed" });
  }
}

async function playProvider(audio: string[], mime: string, my: number) {
  set({ status: "speaking", kind: "provider", message: null });
  for (const b64 of audio) {
    if (my !== token) return;
    await new Promise<void>((resolve, reject) => {
      const el = new Audio(`data:${mime};base64,${b64}`);
      audioEl = el;
      el.onended = () => resolve();
      el.onerror = () => reject(new Error("Audio playback failed"));
      el.play().catch((err) =>
        reject(
          err?.name === "NotAllowedError"
            ? new Error("Your browser blocked audio autoplay - press the speaker button to listen.")
            : err
        )
      );
    });
  }
}

async function playBrowser(chunks: string[], language: string, my: number, note: string | null) {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) {
    throw new Error("This browser cannot speak text aloud (speechSynthesis unavailable).");
  }
  const voice = await pickVoice(language);
  const fallbackNote =
    note || (!voice && language !== "en" ? `No ${language} voice installed; using the default voice.` : null);
  set({ status: "speaking", kind: "browser", message: fallbackNote });
  for (const chunk of chunks) {
    if (my !== token) return;
    await new Promise<void>((resolve, reject) => {
      const u = new SpeechSynthesisUtterance(chunk);
      if (voice) {
        u.voice = voice;
        u.lang = voice.lang;
      } else {
        u.lang = language === "en" ? "en-IN" : language;
      }
      u.onend = () => resolve();
      u.onerror = (ev) => {
        // "canceled"/"interrupted" is our own stop(), not a failure
        if (ev.error === "canceled" || ev.error === "interrupted") resolve();
        else reject(new Error(`Browser speech failed (${ev.error})`));
      };
      window.speechSynthesis.speak(u);
    });
  }
}

function pickVoice(language: string): Promise<SpeechSynthesisVoice | undefined> {
  return new Promise((resolve) => {
    const find = () => {
      const voices = window.speechSynthesis.getVoices();
      return (
        voices.find((v) => v.lang.toLowerCase().startsWith(language.toLowerCase())) ||
        (language === "en" ? voices.find((v) => v.lang.toLowerCase().startsWith("en")) : undefined)
      );
    };
    const now = window.speechSynthesis.getVoices();
    if (now.length) return resolve(find());
    // voices load asynchronously in Chrome
    const timer = setTimeout(() => resolve(find()), 800);
    window.speechSynthesis.onvoiceschanged = () => {
      clearTimeout(timer);
      resolve(find());
    };
  });
}

/** Client-side sentence chunking, used only if the backend is unreachable. */
function localChunks(text: string, limit = 220): string[] {
  const clean = text.replace(/[*_`#>•]+/g, " ").replace(/\s+/g, " ").trim();
  const parts = clean.split(/(?<=[.!?।])\s+/);
  const out: string[] = [];
  let cur = "";
  for (const p of parts) {
    if ((cur + " " + p).trim().length > limit && cur) {
      out.push(cur);
      cur = p;
    } else {
      cur = (cur + " " + p).trim();
    }
  }
  if (cur) out.push(cur);
  return out;
}
